window.QB_TWK_B10 = [
{"id":"TWK-1441","q":"Pancasila disebut sebagai ideologi terbuka. Maksud dari pernyataan tersebut adalah ....","opts":["Pancasila mampu mengikuti perkembangan zaman tanpa mengubah nilai dasarnya","Pancasila hanya berlaku pada masa tertentu dalam sejarah bangsa","Pancasila menerima seluruh paham asing tanpa seleksi","Pancasila dapat diganti dengan ideologi lain sesuai kehendak penguasa","nilai-nilai Pancasila bersifat kaku dan tidak boleh ditafsirkan ulang"],"a":0,"ex":"Ideologi terbuka berarti tidak kaku/dogmatis: nilai dasarnya tetap, tetapi penjabarannya dinamis mengikuti perkembangan zaman."},
{"id":"TWK-1442","q":"Salah satu ciri ideologi terbuka yang melekat pada Pancasila adalah ....","opts":["nilai-nilainya dipaksakan oleh negara kepada seluruh rakyat","nilai-nilainya digali dari budaya dan jati diri bangsa sendiri","menolak setiap perubahan dalam kehidupan bernegara","hanya boleh ditafsirkan oleh pemerintah yang berkuasa","menutup diri dari perkembangan ilmu pengetahuan"],"a":1,"ex":"Keterbukaan Pancasila lahir dari prosesnya: nilai-nilainya bersumber dari budaya bangsa, bukan dipaksakan dari atas secara totaliter."},
{"id":"TWK-1443","q":"Dalam Pancasila sebagai ideologi terbuka, nilai dasar (misalnya Ketuhanan dan Kemanusiaan) bersifat ....","opts":["sama kedudukannya dengan peraturan daerah","hanya berlaku bagi aparatur negara","sementara dan dapat diganti kapan saja","tetap, sedangkan nilai instrumental dapat berkembang","tidak penting dalam kehidupan bernegara"],"a":3,"ex":"Nilai dasar Pancasila bersifat tetap/abadi, sedangkan nilai instrumental (UUD, UU) dan nilai praksis dapat berkembang mengikuti zaman."},
{"id":"TWK-1444","q":"Amandemen UUD 1945 yang dilakukan empat kali pada 1999-2002 tanpa mengubah Pembukaan UUD 1945 menunjukkan bahwa Pancasila sebagai ideologi bersifat ....","opts":["kaku","terbuka","sementara","bebas nilai","tertutup"],"a":1,"ex":"Amandemen membuktikan keterbukaan: penjabaran nilai dapat berubah mengikuti tuntutan reformasi, tetapi nilai dasar dalam Pembukaan tetap dipertahankan."},
{"id":"TWK-1445","q":"Ideologi tertutup pada umumnya bercirikan ....","opts":["mendorong musyawarah dalam pengambilan keputusan","menghargai perbedaan pendapat dan kritik","bersifat totaliter dan memaksakan kehendak penguasa","memberi kebebasan penuh kepada rakyatnya","berasal dari budaya masyarakat setempat"],"a":2,"ex":"Ideologi tertutup bersifat dogmatis, totaliter, tidak menerima kritik, dan dipaksakan dari atas — kebalikan dari ideologi terbuka."},
{"id":"TWK-1446","q":"Komunisme digolongkan sebagai ideologi tertutup. Salah satu ajarannya yang paling bertentangan dengan Pancasila sila pertama adalah ....","opts":["materialisme yang menafikan Tuhan","pemerataan hasil produksi","penghapusan sistem upah","perjuangan kelas buruh","penghapusan hak milik pribadi"],"a":0,"ex":"Ajarannya yang ateis/materialistis menafikan Tuhan sehingga bertentangan langsung dengan sila pertama, Ketuhanan Yang Maha Esa."},
{"id":"TWK-1447","q":"Liberalisme sebagai ideologi menekankan ....","opts":["kepentingan kolektif di atas segalanya","kebebasan individu sebagai nilai tertinggi","peran negara yang sangat dominan","penghapusan hak milik pribadi","persamaan hasil bagi seluruh rakyat"],"a":1,"ex":"Liberalisme menempatkan kebebasan dan hak individu sebagai nilai tertinggi, dengan peran negara yang minimal."},
{"id":"TWK-1448","q":"Perbedaan mendasar antara Pancasila dan liberalisme dalam memandang hak individu adalah ....","opts":["keduanya sama-sama menolak peran negara","Pancasila menghapus kebebasan berpendapat","Pancasila menolak seluruh hak individu warga negara","Pancasila menyeimbangkan hak individu dengan kewajiban sosial","liberalisme lebih mengutamakan gotong royong"],"a":3,"ex":"Pancasila tidak memutlakkan individu seperti liberalisme; hak individu diimbangi kewajiban sosial demi keadilan bersama (sila kedua dan kelima)."},
{"id":"TWK-1449","q":"Sila pertama Pancasila menolak paham ateisme dan sekularisme ekstrem karena ....","opts":["negara mengakui dan menjamin kehidupan beragama rakyatnya","agama hanya urusan pribadi yang tidak boleh tampil di publik","negara menetapkan satu agama resmi","kebebasan beragama dilarang oleh konstitusi","negara wajib mengatur seluruh ritual keagamaan"],"a":0,"ex":"Ketuhanan Yang Maha Esa menegaskan negara berdasar Ketuhanan: mengakui, menghormati, dan menjamin kebebasan beragama (Pasal 29 UUD 1945)."},
{"id":"TWK-1450","q":"Fasisme sebagai ideologi bercirikan ....","opts":["ekonomi kerakyatan yang berkeadilan","demokrasi dan penghormatan hak asasi manusia","ultranasionalisme ekstrem dan kekuasaan totaliter","persamaan derajat seluruh manusia","kebebasan pers dan berpendapat"],"a":2,"ex":"Fasisme (misalnya Italia di bawah Mussolini dan Jerman di bawah Hitler) bercirikan ultranasionalisme, kultus pemimpin, dan kekuasaan totaliter."},
{"id":"TWK-1451","q":"Pancasila menolak fasisme karena fasisme bertentangan dengan ....","opts":["cita-cita kemerdekaan bangsa Indonesia","pentingnya pertahanan dan keamanan negara","kedudukan bahasa Indonesia sebagai bahasa persatuan","semangat persatuan dan kesatuan bangsa","nilai kemanusiaan yang adil dan beradab serta demokrasi"],"a":4,"ex":"Fasisme menindas kemanusiaan dan demokrasi sehingga bertentangan dengan sila kedua (kemanusiaan yang adil dan beradab) dan sila keempat."},
{"id":"TWK-1452","q":"Demokrasi Pancasila berbeda dengan demokrasi liberal karena demokrasi Pancasila ....","opts":["menolak pemilihan umum sebagai sarana demokrasi","mengutamakan musyawarah untuk mencapai mufakat","hanya memberi hak pilih kepada kelompok tertentu","melarang adanya partai politik","menyerahkan keputusan pada suara mayoritas mutlak"],"a":1,"ex":"Demokrasi Pancasila (sila keempat) mengedepankan musyawarah untuk mufakat dengan semangat kekeluargaan, bukan sekadar menang-menangan suara mayoritas."},
{"id":"TWK-1453","q":"Pancasila sebagai ideologi memiliki tiga dimensi, yaitu ....","opts":["dasar, menengah, dan tinggi","individu, masyarakat, dan negara","politik, ekonomi, dan budaya","realistis, idealistis, dan normatif","nasional, regional, dan internasional"],"a":3,"ex":"Tiga dimensi Pancasila sebagai ideologi: realistis (mencerminkan kenyataan), idealistis (cita-cita luhur), dan normatif (mengandung norma yang harus dilaksanakan)."},
{"id":"TWK-1454","q":"Dimensi realistis Pancasila sebagai ideologi mengandung makna ....","opts":["nilai-nilai Pancasila mencerminkan kenyataan hidup bangsa Indonesia","Pancasila harus ditafsirkan secara kaku dan harfiah","Pancasila terlepas dari kondisi nyata masyarakat","Pancasila hanya berlaku dalam tataran teori","Pancasila hanya berisi cita-cita yang sulit dicapai"],"a":0,"ex":"Dimensi realistis berarti nilai Pancasila bukan khayalan, melainkan benar-benar hidup dan mencerminkan kenyataan masyarakat Indonesia."},
{"id":"TWK-1455","q":"Dimensi idealistis Pancasila sebagai ideologi mengandung makna ....","opts":["Pancasila tidak memiliki tujuan jangka panjang","Pancasila memuat cita-cita luhur yang ingin diwujudkan bangsa","Pancasila hanya mengatur hal-hal yang bersifat teknis","Pancasila menolak setiap bentuk perubahan","Pancasila identik dengan peraturan perundang-undangan"],"a":1,"ex":"Dimensi idealistis berarti Pancasila mengandung nilai-nilai cita luhur (ide-ide dasar) yang menjadi tujuan perjuangan bangsa Indonesia."},
{"id":"TWK-1456","q":"Dimensi normatif Pancasila sebagai ideologi mengandung makna ....","opts":["nilai-nilai Pancasila menjadi norma yang wajib dipatuhi dan dilaksanakan","Pancasila tidak mengikat penyelenggara negara","norma Pancasila hanya berlaku di bidang hukum pidana","nilai Pancasila bersifat anjuran yang boleh diabaikan","Pancasila hanya menjadi wacana akademik"],"a":0,"ex":"Dimensi normatif berarti nilai-nilai Pancasila harus dijabarkan menjadi norma hukum dan etika yang mengikat seluruh warga negara."},
{"id":"TWK-1457","q":"Kedudukan Pancasila sebagai sumber dari segala sumber hukum ditegaskan dalam ....","opts":["Ketetapan MPRS No. XX/MPRS/1966 dan UU No. 12 Tahun 2011","UUD 1945 Pasal 37","Ketetapan MPR No. I/MPR/2003","UU No. 5 Tahun 1960","Peraturan Pemerintah No. 6 Tahun 1988"],"a":0,"ex":"TAP MPRS No. XX/MPRS/1966 menegaskan Pancasila sebagai sumber dari segala sumber hukum, ditegaskan kembali dalam UU No. 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-undangan."},
{"id":"TWK-1458","q":"Contoh nilai instrumental Pancasila dalam kehidupan bernegara adalah ....","opts":["lagu kebangsaan Indonesia Raya","kegiatan gotong royong di lingkungan RT","sikap jujur dalam pergaulan sehari-hari","pasal-pasal UUD 1945 dan peraturan perundang-undangan","semboyan Bhinneka Tunggal Ika"],"a":3,"ex":"Nilai instrumental adalah penjabaran nilai dasar ke dalam bentuk yang lebih konkret, misalnya UUD 1945, ketetapan MPR, dan undang-undang."},
{"id":"TWK-1459","q":"Contoh nilai praksis Pancasila adalah ....","opts":["pelaksanaan nilai Pancasila dalam perilaku nyata sehari-hari","naskah akademik suatu rancangan undang-undang","teks pidato kenegaraan Presiden","putusan pengadilan yang berkekuatan hukum tetap","rumusan sila-sila dalam Pembukaan UUD 1945"],"a":0,"ex":"Nilai praksis adalah perwujudan nyata nilai-nilai Pancasila dalam tindakan dan perilaku sehari-hari, baik oleh warga maupun penyelenggara negara."},
{"id":"TWK-1460","q":"Keterbukaan ideologi Pancasila bukan berarti ....","opts":["menjaga nilai dasar yang bersifat tetap","mampu berdialog dengan perkembangan ilmu pengetahuan","menerima setiap paham asing tanpa seleksi dan saringan","menjunjung tinggi nilai kemanusiaan","menyesuaikan diri dengan tuntutan zaman"],"a":2,"ex":"Keterbukaan bukan kebebasan tanpa batas; paham asing harus disaring dan disesuaikan dengan kepribadian serta nilai dasar bangsa Indonesia."},
{"id":"TWK-1461","q":"Sikap selektif terhadap budaya asing merupakan wujud Pancasila sebagai ideologi terbuka karena ....","opts":["menerima budaya asing secara utuh","menutup diri dari pergaulan internasional","menganggap budaya asing lebih unggul","menolak seluruh pengaruh dari luar","menyaring budaya asing sesuai kepribadian bangsa"],"a":4,"ex":"Ideologi terbuka bersifat antisipatif dan selektif: terbuka terhadap hal positif dari luar, tetapi disaring agar sesuai dengan jati diri bangsa."},
{"id":"TWK-1462","q":"Pancasila disebut sebagai kepribadian bangsa Indonesia karena ....","opts":["dirumuskan oleh para pendiri negara dalam sidang BPUPKI","mencerminkan jati diri, watak, dan karakter bangsa Indonesia","ditetapkan melalui Dekret Presiden 5 Juli 1959","merupakan terjemahan dari ideologi bangsa lain","hanya dipahami oleh kalangan terpelajar"],"a":1,"ex":"Pancasila digali dari nilai-nilai budaya bangsa sendiri sehingga mencerminkan kepribadian dan jati diri bangsa Indonesia."},
{"id":"TWK-1463","q":"Ajaran perjuangan kelas dalam Marxisme bertentangan dengan Pancasila terutama sila ....","opts":["kedua saja","pertama saja","pertama dan kedua","ketiga dan kelima","keempat saja"],"a":3,"ex":"Perjuangan kelas memecah belah masyarakat sehingga bertentangan dengan sila ketiga (Persatuan Indonesia) dan sila kelima (keadilan sosial bagi seluruh rakyat)."},
{"id":"TWK-1464","q":"Sistem perekonomian nasional disusun sebagai usaha bersama berdasar atas asas kekeluargaan. Ketentuan tersebut diatur dalam UUD 1945 Pasal ....","opts":["34 ayat (1)","27 ayat (2)","28H ayat (1)","31 ayat (1)","33 ayat (1)"],"a":4,"ex":"Pasal 33 ayat (1) UUD 1945 menegaskan perekonomian disusun sebagai usaha bersama berdasar asas kekeluargaan — menolak kapitalisme liberal maupun etatisme."},
{"id":"TWK-1465","q":"Pancasila disebut aktual sebagai ideologi karena ....","opts":["berlaku surut untuk menilai masa lalu","hanya relevan pada masa perjuangan kemerdekaan","mampu menjawab dan mengikuti perkembangan zaman","tidak pernah mengalami perubahan tafsir","hanya dipelajari di lingkungan sekolah"],"a":2,"ex":"Aktual berarti senantiasa relevan: Pancasila mampu menjawab tantangan dan perkembangan setiap zaman tanpa kehilangan nilai dasarnya."},
{"id":"TWK-1466","q":"Pancasila disebut antisipatif sebagai ideologi karena ....","opts":["menolak perencanaan jangka panjang","hanya berorientasi pada masa kini","menunggu petunjuk dari negara lain","bereaksi setelah masalah terjadi","mampu mengantisipasi perkembangan dan tantangan masa depan"],"a":4,"ex":"Antisipatif berarti ideologi Pancasila mampu memperkirakan arah perkembangan zaman sehingga bangsa siap menghadapi tantangan masa depan."},
{"id":"TWK-1467","q":"Pancasila sebagai ideologi nasional memiliki keunggulan dibanding ideologi impor karena ....","opts":["dirumuskan oleh satu orang tokoh","lahir dari nilai-nilai budaya bangsa Indonesia sendiri","dipaksakan melalui kekuasaan militer","diadopsi dari sistem negara maju","tidak memerlukan pembuktian dalam praktik"],"a":1,"ex":"Pancasila bukan ideologi impor; ia digali dari pandangan hidup dan budaya bangsa Indonesia sehingga sesuai dengan jati diri bangsa."},
{"id":"TWK-1468","q":"Perbedaan pandangan hidup (way of life) dengan ideologi terletak pada ....","opts":["ideologi tidak memengaruhi kebijakan negara","keduanya memiliki makna yang identik","pandangan hidup bersifat abstrak, ideologi lebih operasional","ideologi tidak berkaitan dengan nilai","pandangan hidup hanya milik individu"],"a":2,"ex":"Pandangan hidup bersifat abstrak-filosofis, sedangkan ideologi merupakan penjabaran pandangan hidup yang lebih operasional sebagai pedoman perjuangan dan kebijakan."},
{"id":"TWK-1469","q":"Pancasila sebagai pandangan hidup bangsa berfungsi sebagai ....","opts":["pedoman tingkah laku dan pandangan dalam kehidupan sehari-hari","dasar hukum acara pengadilan","pedoman teknik pembangunan fisik","aturan kepegawaian aparatur negara","alat kekuasaan pemerintah"],"a":0,"ex":"Sebagai pandangan hidup (way of life), Pancasila menjadi kristalisasi nilai yang diyakini kebenarannya dan menjadi pedoman bersikap serta bertingkah laku."},
{"id":"TWK-1470","q":"Komunisme dan Pancasila sama-sama mencita-citakan keadilan sosial, tetapi keduanya berbeda secara mendasar dalam hal ....","opts":["keduanya sama-sama bersifat terbuka","komunisme menolak Ketuhanan dan bersifat materialistis","Pancasila menolak keadilan sosial","komunisme menjunjung tinggi hak asasi manusia","Pancasila menganut sistem kelas"],"a":1,"ex":"Perbedaan mendasarnya: komunisme bersifat materialistis-ateis dan memandang sejarah dari perjuangan kelas, sedangkan Pancasila berdasar Ketuhanan dan persatuan."},
{"id":"TWK-1471","q":"Ajaran materialisme historis yang menafikan Tuhan bertentangan dengan Pancasila sila ....","opts":["pertama","keempat","kelima","kedua","ketiga"],"a":0,"ex":"Materialisme historis menganggap agama sekadar candu masyarakat sehingga bertentangan dengan sila pertama, Ketuhanan Yang Maha Esa."},
{"id":"TWK-1472","q":"Paham individualisme liberal yang mengutamakan kepentingan pribadi di atas kepentingan bersama bertentangan dengan Pancasila sila ....","opts":["pertama","kedua","ketiga dan kelima","keempat","pertama dan keempat"],"a":2,"ex":"Individualisme ekstrem merusak persatuan (sila ketiga) dan keadilan sosial (sila kelima) karena mengabaikan kepentingan bersama."},
{"id":"TWK-1473","q":"Warga sebuah desa bergotong royong memperbaiki jembatan yang rusak tanpa mengharap imbalan. Perilaku tersebut mencerminkan pengamalan Pancasila sila ....","opts":["keempat","kelima","pertama","kedua","ketiga"],"a":4,"ex":"Gotong royong adalah wujud persatuan dan kebersamaan, yang merupakan pengamalan sila ketiga, Persatuan Indonesia."},
{"id":"TWK-1474","q":"Fungsi Pancasila sebagai ideologi nasional dalam masyarakat yang majemuk adalah ....","opts":["mempersatukan keberagaman dalam bingkai NKRI","menghapus perbedaan suku dan agama","menetapkan satu budaya sebagai acuan nasional","membatasi kebebasan berekspresi warga","menyeragamkan seluruh budaya daerah"],"a":0,"ex":"Sebagai ideologi nasional, Pancasila menjadi perekat yang mempersatukan keberagaman suku, agama, dan budaya dalam Negara Kesatuan Republik Indonesia."},
{"id":"TWK-1475","q":"Ancaman nyata terhadap ideologi Pancasila di era digital saat ini adalah ....","opts":["maraknya perdagangan daring","penggunaan bahasa asing dalam percakapan","penyebaran paham radikal dan intoleran melalui media sosial","perkembangan teknologi informasi","banyaknya pengguna internet"],"a":2,"ex":"Ancaman ideologis kini berbentuk penyebaran paham radikal, intoleran, dan disinformasi melalui media sosial yang dapat menggerus nilai Pancasila."},
{"id":"TWK-1476","q":"Upaya yang paling tepat untuk membentengi ideologi Pancasila pada generasi muda adalah ....","opts":["menutup akses informasi dari luar negeri","menyeragamkan seluruh kegiatan kepemudaan","membatasi kebebasan berpendapat generasi muda","melarang generasi muda menggunakan media sosial","pendidikan Pancasila dan penguatan literasi digital"],"a":4,"ex":"Pembentengan ideologi dilakukan melalui pendidikan Pancasila yang hidup dan literasi digital agar generasi muda kritis terhadap paham yang bertentangan dengan Pancasila."},
{"id":"TWK-1477","q":"Nilai Ketuhanan dalam Pancasila menjamin ....","opts":["negara menetapkan satu agama resmi","kebebasan beragama dan kerukunan antarumat beragama","seluruh warga wajib memeluk agama yang sama","agama tidak boleh hadir dalam ruang publik","pemerintah mengatur tata cara ibadah setiap agama"],"a":1,"ex":"Sila pertama menjamin setiap penduduk bebas memeluk agama dan beribadat menurut kepercayaannya, serta hidup rukun antarumat beragama."},
{"id":"TWK-1478","q":"Pancasila menolak sekularisme total yang memisahkan agama dari negara karena ....","opts":["agama hanya boleh dianut secara sembunyi-sembunyi","negara melarang pendirian rumah ibadat","negara Indonesia adalah negara agama","UUD 1945 menjamin kemerdekaan beragama dan negara berdasar Ketuhanan","pemerintah wajib memimpin seluruh ritual keagamaan"],"a":3,"ex":"Indonesia bukan negara sekuler-total: Pasal 29 UUD 1945 menegaskan negara berdasar atas Ketuhanan Yang Maha Esa dan menjamin kemerdekaan beragama."},
{"id":"TWK-1479","q":"Esensi Pancasila sebagai ideologi terbuka terletak pada ....","opts":["keseimbangan antara ketetapan nilai dasar dan dinamika penjabarannya","penolakan terhadap setiap bentuk perubahan","penyeragaman tafsir oleh negara","pemisahan nilai agama dari kehidupan bernegara","kebebasan mengganti nilai dasar sesuai selera"],"a":0,"ex":"Esensi keterbukaan: nilai dasar bersifat tetap sebagai jangkar, sedangkan penjabaran (instrumental dan praksis) dinamis mengikuti perkembangan zaman."},
{"id":"TWK-1480","q":"Reformasi 1998 yang menuntut perubahan ketatanegaraan dapat dipandang sebagai wujud Pancasila sebagai ideologi terbuka karena ....","opts":["nilai dasar Pancasila ikut diubah dalam amandemen","reformasi mengganti Pancasila dengan ideologi baru","tuntutan perubahan disalurkan melalui mekanisme konstitusional tanpa mengganti nilai dasar","reformasi menolak seluruh warisan Orde Baru termasuk Pancasila","perubahan dilakukan dengan kekerasan"],"a":2,"ex":"Reformasi membuktikan keterbukaan Pancasila: aspirasi perubahan disalurkan lewat amandemen konstitusional, sementara nilai dasar dalam Pembukaan UUD 1945 tetap dipertahankan."},
{"id":"TWK-1481","q":"Berdasarkan UUD 1945 Pasal 2 ayat (1), Majelis Permusyawaratan Rakyat terdiri atas ....","opts":["utusan daerah dan utusan golongan","anggota DPR dan perwakilan partai politik","tokoh masyarakat yang ditunjuk Presiden","anggota DPR dan anggota DPD yang dipilih melalui pemilihan umum","menteri-menteri kabinet dan pimpinan lembaga negara"],"a":3,"ex":"Pasal 2 ayat (1) UUD 1945: MPR terdiri atas anggota DPR dan anggota DPD yang dipilih melalui pemilihan umum."},
{"id":"TWK-1482","q":"Jumlah anggota DPR periode 2024-2029 adalah ....","opts":["550 orang","560 orang","575 orang","580 orang","590 orang"],"a":3,"ex":"Jumlah anggota DPR periode 2024-2029 adalah 580 orang, bertambah seiring pemekaran daerah pemilihan."},
{"id":"TWK-1483","q":"Setiap provinsi diwakili oleh anggota DPD sebanyak ....","opts":["5 orang","6 orang","2 orang","3 orang","4 orang"],"a":4,"ex":"UUD 1945 Pasal 22C: anggota DPD dari setiap provinsi jumlahnya sama, yaitu 4 orang, sebagaimana diatur undang-undang."},
{"id":"TWK-1484","q":"Dengan 38 provinsi saat ini, jumlah anggota DPD adalah ....","opts":["136 orang","148 orang","152 orang","160 orang","114 orang"],"a":2,"ex":"38 provinsi dikali 4 orang per provinsi menghasilkan 152 anggota DPD."},
{"id":"TWK-1485","q":"Anggota DPD dipilih dengan cara ....","opts":["ditunjuk oleh Menteri Dalam Negeri","ditunjuk oleh Presiden","dipilih langsung oleh rakyat di setiap provinsi secara perseorangan","diangkat dari pengurus partai politik","dipilih oleh DPRD provinsi"],"a":2,"ex":"Anggota DPD dipilih langsung oleh rakyat melalui pemilu secara perseorangan (bukan dari partai politik) untuk mewakili provinsinya."},
{"id":"TWK-1486","q":"Masa jabatan anggota MPR, DPR, dan DPD adalah ....","opts":["5 tahun","6 tahun","7 tahun","3 tahun","4 tahun"],"a":0,"ex":"Masa jabatan anggota MPR, DPR, dan DPD adalah lima tahun dan berakhir pada saat anggota yang baru mengucapkan sumpah/janji."},
{"id":"TWK-1487","q":"Wewenang MPR menurut UUD 1945 Pasal 3 adalah ....","opts":["membentuk undang-undang bersama Presiden","mengubah dan menetapkan UUD serta melantik dan memberhentikan Presiden/Wakil Presiden","menyusun dan menetapkan APBN","mengangkat dan memberhentikan menteri","memilih ketua Mahkamah Agung"],"a":1,"ex":"Pasal 3 UUD 1945: MPR berwenang mengubah dan menetapkan UUD, melantik Presiden/Wakil Presiden, serta memberhentikan keduanya dalam masa jabatan menurut UUD."},
{"id":"TWK-1488","q":"Presiden dan Wakil Presiden sebelum memangku jabatan mengucapkan sumpah atau janji di hadapan ....","opts":["Mahkamah Konstitusi","Komisi Pemilihan Umum","Mahkamah Agung","Dewan Perwakilan Rakyat","Majelis Permusyawaratan Rakyat"],"a":4,"ex":"MPR melantik Presiden dan Wakil Presiden; keduanya mengucapkan sumpah/janji menurut agamanya di hadapan sidang MPR."},
{"id":"TWK-1489","q":"Sidang MPR untuk mengubah UUD 1945 sah apabila dihadiri sekurang-kurangnya ....","opts":["2/3 dari jumlah anggota MPR","3/4 dari jumlah anggota MPR","seluruh anggota MPR","1/3 dari jumlah anggota MPR","1/2 dari jumlah anggota MPR"],"a":0,"ex":"Pasal 37 ayat (3) UUD 1945: untuk mengubah pasal-pasal UUD, sidang MPR dihadiri sekurang-kurangnya 2/3 dari jumlah anggota MPR."},
{"id":"TWK-1490","q":"Putusan perubahan UUD 1945 sah apabila disetujui sekurang-kurangnya ....","opts":["seluruh anggota MPR tanpa kecuali","1/2 dari anggota yang hadir","2/3 dari anggota yang hadir","50 persen ditambah satu dari seluruh anggota MPR","3/4 dari seluruh anggota MPR"],"a":3,"ex":"Pasal 37 ayat (4) UUD 1945: putusan untuk mengubah pasal-pasal UUD disetujui sekurang-kurangnya lima puluh persen ditambah satu dari seluruh anggota MPR."},
{"id":"TWK-1491","q":"Segala putusan MPR ditetapkan dengan ....","opts":["keputusan Ketua MPR","penunjukan langsung oleh Presiden","undian di antara anggota yang hadir","pemungutan suara sejak awal","musyawarah untuk mencapai mufakat; bila tidak tercapai baru pemungutan suara"],"a":4,"ex":"Pasal 2 ayat (3) UUD 1945 menetapkan putusan MPR dengan suara yang terbanyak; dalam praktiknya MPR mengupayakan musyawarah untuk mufakat terlebih dahulu, dan bila tidak tercapai baru dilakukan pemungutan suara."},
{"id":"TWK-1492","q":"MPR bersidang sedikitnya sekali dalam ....","opts":["satu tahun","dua tahun","tiga tahun","lima tahun","sepuluh tahun"],"a":3,"ex":"Pasal 2 ayat (2) UUD 1945: MPR bersidang sedikitnya sekali dalam lima tahun di ibu kota negara."},
{"id":"TWK-1493","q":"Tiga fungsi DPR menurut UUD 1945 Pasal 20A adalah fungsi ....","opts":["pembinaan, pengawasan, dan penindakan","regulator, operator, dan fasilitator","legislasi, eksekusi, dan yudikasi","legislasi, anggaran, dan pengawasan","politik, ekonomi, dan budaya"],"a":3,"ex":"Pasal 20A ayat (1) UUD 1945: DPR memiliki fungsi legislasi, fungsi anggaran, dan fungsi pengawasan."},
{"id":"TWK-1494","q":"Fungsi legislasi DPR diwujudkan melalui kewenangan ....","opts":["menetapkan APBN setiap tahun","mengawasi jalannya pemerintahan","memilih anggota BPK","memberikan grasi dan rehabilitasi","membentuk undang-undang bersama Presiden"],"a":4,"ex":"Pasal 20 ayat (1)-(2) UUD 1945: DPR memegang kekuasaan membentuk undang-undang dan setiap rancangan UU dibahas bersama Presiden untuk mendapat persetujuan bersama."},
{"id":"TWK-1495","q":"Fungsi anggaran DPR berkaitan dengan kewenangan ....","opts":["mengatur belanja partai politik","menetapkan pajak daerah","membahas dan menyetujui APBN yang diusulkan Presiden","mengelola kas negara","menentukan gaji pegawai negeri"],"a":2,"ex":"Dalam fungsi anggaran, DPR membahas dan memberikan persetujuan atau tidak memberikan persetujuan terhadap RAPBN yang diajukan Presiden (Pasal 23)."},
{"id":"TWK-1496","q":"Apabila DPR tidak menyetujui RAPBN yang diusulkan Presiden, maka ....","opts":["DPR wajib menyusun APBN sendiri","APBN dibatalkan untuk tahun berjalan","MPR mengambil alih penetapan APBN","Presiden menetapkan APBN melalui Perppu","pemerintah menjalankan APBN tahun yang lalu"],"a":4,"ex":"Pasal 23 ayat (3) UUD 1945: apabila DPR tidak menyetujui RAPBN yang diusulkan Presiden, pemerintah menjalankan APBN tahun yang lalu."},
{"id":"TWK-1497","q":"Fungsi pengawasan DPR dilaksanakan dalam bentuk ....","opts":["pengawasan atas pelaksanaan undang-undang, APBN, dan kebijakan pemerintah","pemeriksaan keuangan negara secara langsung","penyidikan tindak pidana korupsi","pengadilan terhadap pejabat negara","penetapan peraturan daerah"],"a":0,"ex":"Fungsi pengawasan DPR meliputi pengawasan terhadap pelaksanaan UU, APBN, serta kebijakan pemerintah sesuai peraturan perundang-undangan."},
{"id":"TWK-1498","q":"Hak interpelasi DPR adalah hak untuk ....","opts":["mengajukan calon pejabat negara","membatalkan peraturan pemerintah","menyelidiki dugaan pelanggaran hukum oleh pejabat","meminta keterangan kepada pemerintah mengenai kebijakan penting dan strategis","menyatakan pendapat terhadap suatu peristiwa"],"a":3,"ex":"Hak interpelasi adalah hak DPR meminta keterangan kepada pemerintah mengenai kebijakan pemerintah yang penting dan strategis serta berdampak luas."},
{"id":"TWK-1499","q":"Hak angket DPR adalah hak untuk ....","opts":["melakukan penyelidikan terhadap pelaksanaan suatu undang-undang atau kebijakan yang diduga bertentangan dengan peraturan","menyatakan pendapat atas kejadian luar biasa","mengajukan rancangan undang-undang","memberhentikan Presiden","meminta keterangan mengenai kebijakan pemerintah"],"a":0,"ex":"Hak angket adalah hak DPR untuk melakukan penyelidikan terhadap pelaksanaan suatu UU dan/atau kebijakan pemerintah yang diduga bertentangan dengan peraturan perundang-undangan."},
{"id":"TWK-1500","q":"Hak DPR untuk menyatakan pendapat berkaitan dengan ....","opts":["penyusunan kurikulum pendidikan","kebijakan pemerintah atau kejadian luar biasa di dalam maupun luar negeri","pengangkatan duta besar","penetapan hari libur nasional","pemilihan ketua umum partai politik"],"a":1,"ex":"Hak menyatakan pendapat adalah hak DPR sebagai lembaga untuk menyatakan pendapat terhadap kebijakan pemerintah atau kejadian luar biasa, termasuk dugaan pelanggaran hukum oleh Presiden/Wakil Presiden."},
{"id":"TWK-1501","q":"Presiden tidak dapat membekukan dan/atau membubarkan DPR. Ketentuan tersebut diatur dalam UUD 1945 Pasal ....","opts":["7C","8","9","7A","7B"],"a":0,"ex":"Pasal 7C UUD 1945 menegaskan Presiden tidak dapat membekukan dan/atau membubarkan DPR sebagai jaminan kemandirian lembaga legislatif."},
{"id":"TWK-1502","q":"Hak imunitas anggota DPR mengandung makna ....","opts":["anggota DPR kebal dari seluruh tuntutan hukum","anggota DPR tidak dapat dituntut karena pernyataan dan pendapat dalam rapat DPR","anggota DPR bebas melakukan tindak pidana","anggota DPR tidak wajib membayar pajak","anggota DPR dapat menolak pemeriksaan aparat"],"a":1,"ex":"Hak imunitas melindungi anggota DPR dari tuntutan hukum atas pernyataan, pertanyaan, dan pendapat yang disampaikan dalam rapat-rapat DPR sesuai peraturan perundang-undangan."},
{"id":"TWK-1503","q":"Menurut UUD 1945 Pasal 22D, DPD dapat mengajukan rancangan undang-undang kepada DPR yang berkaitan dengan ....","opts":["sistem peradilan dan kehakiman","pendidikan nasional secara umum","pertahanan dan keamanan negara","otonomi daerah, hubungan pusat dan daerah, serta pengelolaan sumber daya alam","politik luar negeri dan perjanjian internasional"],"a":3,"ex":"Pasal 22D ayat (1): DPD dapat mengajukan kepada DPR rancangan UU tentang otonomi daerah, hubungan pusat-daerah, pembentukan/pemekaran/penggabungan daerah, dan pengelolaan SDA serta sumber daya ekonomi lainnya."},
{"id":"TWK-1504","q":"DPD memberikan pertimbangan kepada DPR atas rancangan undang-undang yang berkaitan dengan ....","opts":["pertahanan, keamanan, dan intelijen","pemilihan umum dan partai politik","hubungan luar negeri","hukum pidana dan perdata","APBN, pajak, pendidikan, dan agama"],"a":4,"ex":"Pasal 22D ayat (2) UUD 1945: DPD memberikan pertimbangan atas rancangan UU tentang APBN, pajak, pendidikan, dan agama."},
{"id":"TWK-1505","q":"DPD melakukan pengawasan atas pelaksanaan undang-undang mengenai ....","opts":["hanya tentang otonomi daerah","hanya tentang APBN","otonomi daerah, pembentukan daerah, hubungan pusat-daerah, SDA, APBN, pajak, pendidikan, dan agama","hanya tentang pendidikan","seluruh peraturan perundang-undangan tanpa batas"],"a":2,"ex":"Pasal 22D ayat (3): DPD melakukan pengawasan atas pelaksanaan UU mengenai otonomi daerah, pembentukan/pemekaran/penggabungan daerah, hubungan pusat-daerah, pengelolaan SDA dan sumber daya ekonomi lain, APBN, pajak, pendidikan, dan agama."},
{"id":"TWK-1506","q":"Perbedaan utama keanggotaan DPR dan DPD adalah ....","opts":["anggota DPD masa jabatannya lebih lama","anggota DPR tidak dipilih melalui pemilu","anggota DPD berasal dari kalangan militer","anggota DPR dipilih rakyat, anggota DPD ditunjuk Presiden","anggota DPR berasal dari partai politik, anggota DPD perseorangan mewakili provinsi"],"a":4,"ex":"Anggota DPR dicalonkan oleh partai politik peserta pemilu, sedangkan anggota DPD dicalonkan secara perseorangan untuk mewakili provinsinya."},
{"id":"TWK-1507","q":"Pimpinan MPR, DPR, dan DPD terdiri atas ....","opts":["seorang ketua yang ditunjuk Presiden","seorang ketua dan beberapa wakil ketua yang dipilih dari dan oleh anggota","dewan pimpinan yang diangkat MPR","seorang ketua seumur hidup","pimpinan kolektif dari perwakilan fraksi"],"a":1,"ex":"Pimpinan MPR, DPR, dan DPD terdiri atas seorang ketua dan wakil ketua yang dipilih dari dan oleh anggota masing-masing lembaga."},
{"id":"TWK-1508","q":"Rancangan undang-undang yang telah mendapat persetujuan bersama antara DPR dan Presiden ....","opts":["diajukan ke Mahkamah Konstitusi","ditetapkan melalui ketetapan MPR","langsung berlaku tanpa pengesahan","disahkan oleh Presiden menjadi undang-undang","dibahas kembali oleh DPD"],"a":3,"ex":"Pasal 20 ayat (4) UUD 1945: Presiden mengesahkan rancangan UU yang telah disetujui bersama untuk menjadi undang-undang."},
{"id":"TWK-1509","q":"Apabila Presiden tidak mengesahkan rancangan undang-undang dalam waktu tiga puluh hari sejak disetujui bersama, maka ....","opts":["rancangan UU tersebut sah menjadi UU dan wajib diundangkan","DPR membatalkan rancangan UU tersebut","MPR mengambil alih pengesahan","rancangan UU dibahas ulang dari awal","rancangan UU tersebut gugur"],"a":0,"ex":"Pasal 20 ayat (5) UUD 1945: rancangan UU yang tidak disahkan Presiden dalam 30 hari sah menjadi UU dan wajib diundangkan."},
{"id":"TWK-1510","q":"Sebelum amandemen UUD 1945, MPR berkedudukan sebagai lembaga tertinggi negara. Setelah amandemen, kedudukan MPR ....","opts":["hanya sebagai lembaga penasihat Presiden","tetap sebagai lembaga tertinggi negara","sejajar dengan lembaga-lembaga negara lainnya","berada di bawah DPR","dihapuskan dari sistem ketatanegaraan"],"a":2,"ex":"Setelah amandemen, tidak ada lagi lembaga tertinggi; MPR sejajar dengan lembaga negara lain (Presiden, DPR, DPD, MA, MK, BPK, KY)."},
{"id":"TWK-1511","q":"DPD dibentuk melalui perubahan UUD 1945, yaitu ....","opts":["amandemen ketiga tahun 2001","amandemen keempat tahun 2002","Dekret Presiden 5 Juli 1959","amandemen pertama tahun 1999","amandemen kedua tahun 2000"],"a":0,"ex":"DPD dibentuk melalui amandemen ketiga UUD 1945 (2001) yang mengatur DPD dalam Pasal 22C dan 22D."},
{"id":"TWK-1512","q":"Tujuan utama pembentukan DPD adalah ....","opts":["menggantikan peran DPR","memperkuat representasi dan memperjuangkan aspirasi daerah","mengurangi jumlah anggota MPR","mempercepat pembentukan undang-undang","menampung perwakilan golongan fungsional"],"a":1,"ex":"DPD dibentuk untuk memperkuat representasi daerah dalam proses pengambilan keputusan nasional, terutama yang menyangkut kepentingan daerah."},
{"id":"TWK-1513","q":"Calon anggota DPD harus memenuhi syarat, di antaranya ....","opts":["menjabat sebagai kepala daerah","berasal dari kalangan pegawai negeri","menjadi pengurus partai politik","bukan pengurus partai politik dan bertempat tinggal di provinsi yang diwakili","berusia minimal 17 tahun"],"a":3,"ex":"Anggota DPD dicalonkan secara perseorangan; syaratnya antara lain bukan pengurus partai politik dan berdomisili di provinsi yang diwakilinya."},
{"id":"TWK-1514","q":"MPR dapat memberhentikan Presiden dan/atau Wakil Presiden dalam masa jabatannya apabila ....","opts":["terbukti melakukan pelanggaran hukum menurut putusan Mahkamah Konstitusi atas usul DPR","Presiden menolak menghadiri sidang MPR","adanya petisi dari masyarakat","Presiden mengganti para menteri","DPR mengusulkan tanpa alasan"],"a":0,"ex":"Pasal 7A dan 7B UUD 1945: pemberhentian didahului pendapat DPR, diperiksa dan diputus MK, kemudian MPR memutuskan memberhentikan atau tidak."},
{"id":"TWK-1515","q":"Putusan Mahkamah Konstitusi atas pendapat DPR mengenai dugaan pelanggaran oleh Presiden menjadi dasar bagi MPR untuk ....","opts":["membubarkan DPR","membentuk undang-undang baru","menyelenggarakan sidang memutuskan pemberhentian Presiden","memilih Wakil Presiden yang baru","mengubah UUD 1945"],"a":2,"ex":"Apabila MK memutuskan Presiden terbukti melanggar, DPR meneruskan usul pemberhentian ke MPR yang kemudian bersidang untuk memutuskan."},
{"id":"TWK-1516","q":"Setiap rancangan undang-undang dibahas oleh DPR dan Presiden untuk mendapatkan ....","opts":["pengesahan MPR","dukungan DPD","persetujuan Mahkamah Konstitusi","keputusan Mahkamah Agung","persetujuan bersama"],"a":4,"ex":"Pasal 20 ayat (2) UUD 1945: setiap rancangan UU dibahas oleh DPR dan Presiden untuk mendapat persetujuan bersama."},
{"id":"TWK-1517","q":"Dalam pembahasan rancangan undang-undang yang berkaitan dengan kewenangannya, DPD ....","opts":["tidak dilibatkan sama sekali","ikut membahas bersama DPR","memiliki hak veto atas keputusan DPR","mengesahkan rancangan UU","menggantikan peran Presiden"],"a":1,"ex":"Pasal 22D ayat (2): DPD ikut membahas rancangan UU yang berkaitan dengan kewenangannya dan memberikan pertimbangan kepada DPR."},
{"id":"TWK-1518","q":"Keanggotaan MPR saat ini berjumlah ....","opts":["732 orang","700 orang","575 orang","580 orang","692 orang"],"a":0,"ex":"MPR terdiri dari 580 anggota DPR ditambah 152 anggota DPD, sehingga berjumlah 732 anggota."},
{"id":"TWK-1519","q":"Sidang MPR yang melantik Presiden dan Wakil Presiden dipimpin oleh ....","opts":["pimpinan MPR","Ketua DPR","Ketua DPD","Presiden sebelumnya","Ketua Mahkamah Agung"],"a":0,"ex":"Pelantikan Presiden dan Wakil Presiden dilaksanakan dalam sidang MPR yang dipimpin oleh pimpinan MPR."},
{"id":"TWK-1520","q":"Apabila Presiden dan Wakil Presiden berhalangan tetap secara bersamaan, maka yang melaksanakan tugas kepresidenan adalah ....","opts":["Ketua Mahkamah Konstitusi","Ketua MPR","Menteri Dalam Negeri, Menteri Luar Negeri, dan Menteri Pertahanan secara bersama-sama","Ketua DPR","Panglima TNI"],"a":2,"ex":"Pasal 8 ayat (3) UUD 1945: jika Presiden dan Wapres mangkat/berhenti/diberhentikan/berhalangan tetap, pelaksana tugas kepresidenan adalah Mendagri, Menlu, dan Menhan bersama-sama."},
{"id":"TWK-1521","q":"Belanda menyerah kepada Jepang di Kalijati pada tanggal ....","opts":["17 Agustus 1942","29 April 1942","7 Desember 1941","1 Maret 1942","8 Maret 1942"],"a":4,"ex":"Belanda menyerah tanpa syarat kepada Jepang dalam Perjanjian Kalijati pada 8 Maret 1942, menandai awal pendudukan Jepang di Indonesia."},
{"id":"TWK-1522","q":"Pada masa pendudukan Jepang, Pulau Jawa dan Sumatra diperintah oleh ....","opts":["pemerintahan sipil pribumi","Gunseikan dari Angkatan Darat Jepang","Kaigun dari Angkatan Laut Jepang","residen-residen Belanda","para daimyo Jepang"],"a":1,"ex":"Jawa dan Sumatra diperintah Gunseikan (pemerintahan militer AD Jepang), sedangkan Kalimantan, Sulawesi, dan Indonesia Timur diperintah AL Jepang (Minseibu)."},
{"id":"TWK-1523","q":"Gerakan Tiga A yang dipropagandakan Jepang berisi semboyan ....","opts":["Asia Timur Raya bersatu","Jepang saudara kandung Indonesia","Asia untuk bangsa Asia","Nippon Cahaya Asia, Nippon Pelindung Asia, Nippon Pemimpin Asia","Merdeka atau mati"],"a":3,"ex":"Gerakan 3A (1942) mempropagandakan Jepang sebagai Cahaya Asia, Pelindung Asia, dan Pemimpin Asia; dipimpin Syamsuddin dan dibubarkan November 1942."},
{"id":"TWK-1524","q":"Organisasi Putera (Pusat Tenaga Rakyat) dibentuk Jepang pada 16 April 1943 dan dipimpin oleh Empat Serangkai, yaitu ....","opts":["Sukarno, Hatta, Ki Hajar Dewantara, dan KH Mas Mansur","Hatta, Agus Salim, Cokroaminoto, dan Dahlan","Sukarno, Supriyadi, Gatot Mangkupraja, dan Sudirman","Ki Hajar Dewantara, Dewi Sartika, Cut Nyak Dien, dan R.A. Kartini","Sukarno, Hatta, Sjahrir, dan Tan Malaka"],"a":0,"ex":"Empat Serangkai pemimpin Putera adalah Ir. Sukarno, Drs. Moh. Hatta, Ki Hajar Dewantara, dan KH Mas Mansur."},
{"id":"TWK-1525","q":"Organisasi yang menggantikan Putera pada tahun 1944 adalah ....","opts":["Fujinkai","Gerakan Tiga A","Jawa Hokokai","Masyumi","Seinendan"],"a":2,"ex":"Putera dibubarkan dan diganti Jawa Hokokai (Himpunan Kebaktian Jawa) pada Maret 1944 untuk mengerahkan tenaga rakyat bagi perang."},
{"id":"TWK-1526","q":"MIAI (Majelis Islam A'la Indonesia) dibubarkan Jepang dan diganti dengan ....","opts":["Muhammadiyah","Persis","Al-Irsyad","Masyumi pada November 1943","Nahdlatul Ulama"],"a":3,"ex":"Jepang membubarkan MIAI dan membentuk Masyumi (Majelis Syuro Muslimin Indonesia) pada November 1943 sebagai wadah tunggal umat Islam."},
{"id":"TWK-1527","q":"PETA (Pembela Tanah Air) dibentuk pada 3 Oktober 1943 atas usul ....","opts":["Ir. Sukarno","Gatot Mangkupraja","Drs. Moh. Hatta","Jenderal Sudirman","Supriyadi"],"a":1,"ex":"Pembentukan PETA diusulkan oleh Gatot Mangkupraja kepada Gunseikan sebagai kesatuan militer pribumi untuk membantu pertahanan Jepang."},
{"id":"TWK-1528","q":"Heiho pada masa pendudukan Jepang adalah ....","opts":["polisi rahasia Jepang","pasukan bunuh diri Jepang","barisan pemuda terlatih","pembantu prajurit Jepang dalam kemiliteran","organisasi wanita Jepang"],"a":3,"ex":"Heiho adalah barisan pembantu prajurit Jepang yang direkrut dari pemuda Indonesia untuk membantu tugas-tugas kemiliteran."},
{"id":"TWK-1529","q":"Seinendan dan Keibodan yang dibentuk Jepang masing-masing merupakan ....","opts":["barisan pemuda dan barisan pembantu polisi","tentara reguler dan tentara cadangan","organisasi buruh dan organisasi tani","partai politik dan serikat pekerja","barisan wanita dan barisan anak-anak"],"a":0,"ex":"Seinendan adalah barisan pemuda, sedangkan Keibodan adalah barisan pembantu polisi — keduanya untuk pengerahan tenaga rakyat."},
{"id":"TWK-1530","q":"Romusa pada masa pendudukan Jepang adalah ....","opts":["mata uang yang berlaku saat itu","pajak yang dibayar rakyat kepada Jepang","kerja paksa rakyat untuk kepentingan perang Jepang","wajib militer bagi pemuda Indonesia","sistem tanam paksa ala Jepang"],"a":2,"ex":"Romusa (romusha) adalah pengerahan tenaga rakyat secara paksa untuk proyek-proyek militer Jepang dalam kondisi yang sangat berat."},
{"id":"TWK-1531","q":"Fujinkai yang dibentuk pada masa pendudukan Jepang merupakan organisasi ....","opts":["buruh","tani","pelajar","pemuda","wanita"],"a":4,"ex":"Fujinkai adalah organisasi perkumpulan wanita bentukan Jepang untuk mengerahkan kaum perempuan dalam kegiatan perang."},
{"id":"TWK-1532","q":"Tonarigumi yang dibentuk Jepang setara dengan ....","opts":["kabupaten","kecamatan","rukun tetangga","desa","provinsi"],"a":2,"ex":"Tonarigumi adalah organisasi rukun tetangga bentukan Jepang sebagai alat pengawasan dan pengerahan rakyat hingga tingkat terkecil."},
{"id":"TWK-1533","q":"Seikerei yang diwajibkan Jepang kepada rakyat Indonesia adalah kewajiban ....","opts":["mengikuti wajib militer","menyerahkan hasil panen","membayar pajak perang","memberi hormat dengan membungkuk ke arah Tokyo","berbahasa Jepang setiap hari"],"a":3,"ex":"Seikerei adalah kewajiban membungkukkan badan ke arah Tokyo sebagai penghormatan kepada Kaisar Jepang setiap pagi."},
{"id":"TWK-1534","q":"Kinrohosi pada masa pendudukan Jepang adalah ....","opts":["upacara penghormatan kaisar","latihan kemiliteran pemuda","sekolah bahasa Jepang","pajak hasil bumi","kerja bakti untuk kepentingan perang"],"a":4,"ex":"Kinrohosi adalah kerja bakti/pengerahan tenaga rakyat untuk kepentingan perang Jepang, misalnya membangun kubu pertahanan."},
{"id":"TWK-1535","q":"Kebijakan Jepang dalam bidang bahasa pada masa pendudukannya adalah ....","opts":["menetapkan bahasa Inggris sebagai bahasa resmi","melarang bahasa Indonesia dan mewajibkan bahasa Belanda","melarang bahasa Belanda dan menjadikan bahasa Indonesia bahasa resmi","mewajibkan seluruh rakyat berbahasa Jepang","melarang semua bahasa daerah"],"a":2,"ex":"Jepang melarang penggunaan bahasa Belanda dan menetapkan bahasa Indonesia sebagai bahasa resmi, sehingga bahasa Indonesia berkembang pesat."},
{"id":"TWK-1536","q":"Kebijakan ekonomi autarki yang diterapkan Jepang bertujuan ....","opts":["mengembangkan perdagangan internasional","memberantas kemiskinan di desa","membangun industri berat Indonesia","meningkatkan kesejahteraan rakyat Indonesia","memenuhi kebutuhan perang Jepang melalui swasembada di tiap daerah"],"a":4,"ex":"Autarki adalah kebijakan tiap daerah harus mencukupi kebutuhannya sendiri demi mendukung perang; hasil bumi rakyat dirampas untuk keperluan militer Jepang."},
{"id":"TWK-1537","q":"Perlawanan rakyat Singaparna, Tasikmalaya terhadap Jepang dipimpin oleh ....","opts":["H. Madriyan","KH Zainal Musthafa","Supriyadi","Tengku Abdul Jalil","Pang Suma"],"a":1,"ex":"Perlawanan Singaparna (Februari 1944) dipimpin KH Zainal Musthafa karena menolak seikerei dan penderitaan akibat romusa."},
{"id":"TWK-1538","q":"Perlawanan rakyat Indramayu terhadap Jepang pada tahun 1944 dipimpin oleh ....","opts":["Gatot Mangkupraja","Ki Hajar Dewantara","KH Zainal Musthafa","H. Madriyan","Supriyadi"],"a":3,"ex":"Perlawanan Indramayu dipimpin H. Madriyan sebagai protes atas pungutan padi yang memberatkan rakyat."},
{"id":"TWK-1539","q":"Pemberontakan PETA di Blitar pada 14 Februari 1945 dipimpin oleh ....","opts":["Jenderal Sudirman","Supriyadi","KH Mas Mansur","Sukarno","Gatot Mangkupraja"],"a":1,"ex":"Pemberontakan PETA Blitar dipimpin Supriyadi (shodanco) pada 14 Februari 1945 sebagai perlawanan terhadap kekejaman Jepang."},
{"id":"TWK-1540","q":"Perlawanan terhadap Jepang di Aceh dipimpin oleh ....","opts":["Teuku Cik Ditiro","Teuku Umar","Tengku Abdul Jalil","Cut Nyak Dien","Panglima Polim"],"a":2,"ex":"Perlawanan di Cot Plieng, Aceh dipimpin Tengku Abdul Jalil yang menolak pendudukan Jepang."},
{"id":"TWK-1541","q":"Perlawanan terhadap Jepang di Kalimantan Barat dipimpin oleh ....","opts":["Tjilik Riwut","Pattimura","Hasanuddin","Pang Suma","Antang"],"a":3,"ex":"Perlawanan rakyat Dayak di Kalimantan Barat dipimpin Pang Suma menentang kesewenangan Jepang."},
{"id":"TWK-1542","q":"Jepang menyerah kepada Sekutu pada tanggal ....","opts":["6 Agustus 1945","9 Agustus 1945","14 Agustus 1945","17 Agustus 1945","2 September 1945"],"a":2,"ex":"Jepang menyerah pada 14 Agustus 1945 (diumumkan Kaisar Hirohito pada 15 Agustus) setelah Hiroshima dan Nagasaki dibom atom."},
{"id":"TWK-1543","q":"Kota Hiroshima dan Nagasaki dijatuhi bom atom masing-masing pada tanggal ....","opts":["14 dan 15 Agustus 1945","7 dan 8 Desember 1941","6 dan 9 Agustus 1945","9 dan 14 Agustus 1945","1 dan 6 Agustus 1945"],"a":2,"ex":"Hiroshima dibom pada 6 Agustus 1945 dan Nagasaki pada 9 Agustus 1945, yang memaksa Jepang menyerah."},
{"id":"TWK-1544","q":"Janji kemerdekaan kepada Indonesia diucapkan oleh Perdana Menteri Jepang Koiso pada tanggal ....","opts":["29 April 1945","1 Maret 1945","7 Agustus 1945","8 Maret 1942","7 September 1944"],"a":4,"ex":"PM Kuniaki Koiso menjanjikan kemerdekaan bagi Indonesia di kemudian hari pada 7 September 1944."},
{"id":"TWK-1545","q":"Cuo Sangi In yang dibentuk Jepang merupakan ....","opts":["organisasi kepemudaan","tentara sukarela pribumi","badan pertimbangan pusat","pengadilan militer Jepang","dewan ekonomi perang"],"a":2,"ex":"Cuo Sangi In (Chuo Sangi In) adalah Badan Pertimbangan Pusat bentukan Jepang yang beranggotakan tokoh-tokoh Indonesia."},
{"id":"TWK-1546","q":"Tujuan utama Jepang membentuk berbagai organisasi seperti Putera, Jawa Hokokai, dan PETA adalah ....","opts":["mempersiapkan kemerdekaan Indonesia","mengembangkan kebudayaan Indonesia","memberantas buta huruf","memajukan pendidikan rakyat Indonesia","mengerahkan tenaga dan sumber daya rakyat untuk memenangkan perang"],"a":4,"ex":"Semua organisasi bentukan Jepang bertujuan mengerahkan tenaga, sumber daya, dan simpati rakyat demi kemenangan Jepang dalam Perang Asia Timur Raya."},
{"id":"TWK-1547","q":"Dampak positif pendudukan Jepang bagi perjuangan kemerdekaan Indonesia adalah ....","opts":["perekonomian rakyat semakin makmur","bahasa Indonesia berkembang dan muncul pemimpin terlatih militer dari PETA","Belanda kembali berkuasa","rakyat bebas menentukan nasib sendiri","tidak ada penderitaan rakyat"],"a":1,"ex":"Sisi positifnya: bahasa Indonesia berkembang sebagai bahasa resmi dan lahir kader-kader militer terlatih dari PETA yang berperan dalam revolusi fisik."},
{"id":"TWK-1548","q":"Pengerahan romusa terutama digunakan Jepang untuk ....","opts":["membangun rumah ibadah","memperbaiki jalan desa","membangun sekolah-sekolah","membangun kubu pertahanan dan proyek militer","mengembangkan pertanian rakyat"],"a":3,"ex":"Tenaga romusa dikerahkan untuk membangun kubu pertahanan, lapangan udara, dan proyek militer Jepang dalam kondisi kerja yang sangat berat."},
{"id":"TWK-1549","q":"Setelah Jepang menyerah, kekosongan kekuasaan (vacuum of power) di Indonesia dimanfaatkan para pemuda untuk ....","opts":["mendesak Sukarno-Hatta segera memproklamasikan kemerdekaan","menyerahkan kekuasaan kepada Belanda","membentuk pemerintahan militer","melakukan perundingan dengan Jepang","menunggu kedatangan Sekutu"],"a":0,"ex":"Kekosongan kekuasaan dimanfaatkan dengan peristiwa Rengasdengklok: para pemuda mendesak Sukarno-Hatta segera memproklamasikan kemerdekaan Indonesia."},
{"id":"TWK-1550","q":"Pada masa pendudukan Jepang, lagu Indonesia Raya dan bendera Merah Putih ....","opts":["hanya boleh dikibarkan di istana","dilarang sepenuhnya hingga Jepang menyerah","semula dilarang, kemudian diizinkan sebagai alat propaganda Jepang","tidak pernah dikenal rakyat","diganti dengan lagu dan bendera Jepang"],"a":2,"ex":"Jepang semula melarang simbol kebangsaan, tetapi kemudian mengizinkannya sebagai alat propaganda untuk menarik simpati rakyat."},
{"id":"TWK-1551","q":"Agama-agama yang diakui secara resmi di Indonesia adalah ....","opts":["Islam dan Kristen saja","seluruh agama yang dianut warga negara","Islam, Hindu, dan Buddha","Islam, Kristen, Katolik, Hindu, dan Buddha","Islam, Kristen Protestan, Katolik, Hindu, Buddha, dan Konghucu"],"a":4,"ex":"Enam agama yang diakui: Islam, Kristen (Protestan), Katolik, Hindu, Buddha, dan Konghucu."},
{"id":"TWK-1552","q":"Dasar hukum yang mengatur tentang pencegahan penodaan agama di Indonesia adalah ....","opts":["UU No. 5 Tahun 1960","UU PNPS No. 1 Tahun 1965","UU No. 12 Tahun 2011","UU No. 39 Tahun 1999","UU No. 23 Tahun 2006"],"a":1,"ex":"UU PNPS No. 1 Tahun 1965 tentang Pencegahan Penyalahgunaan dan/atau Penodaan Agama menjadi dasar hukumnya."},
{"id":"TWK-1553","q":"UUD 1945 Pasal 29 ayat (2) menegaskan bahwa ....","opts":["pemerintah mengatur tata cara ibadah","kebebasan beragama dibatasi undang-undang","negara menetapkan satu agama resmi","negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing","agama adalah urusan pribadi semata"],"a":3,"ex":"Pasal 29 ayat (2): negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan beribadat menurut agamanya."},
{"id":"TWK-1554","q":"UUD 1945 Pasal 28E ayat (1) menegaskan bahwa setiap orang bebas ....","opts":["memeluk agama dan beribadat menurut agamanya","memaksakan keyakinannya kepada orang lain","menodai agama yang berbeda","menolak seluruh ajaran agama","mendirikan negara berdasarkan agama"],"a":0,"ex":"Pasal 28E ayat (1): setiap orang bebas memeluk agama dan beribadat menurut agamanya, memilih pendidikan, pekerjaan, dan kewarganegaraan."},
{"id":"TWK-1555","q":"Tri kerukunan umat beragama meliputi ....","opts":["kerukunan antara pusat dan daerah","kerukunan intern umat beragama, antarumat beragama, dan umat beragama dengan pemerintah","kerukunan antar suku, antar ras, dan antar golongan","kerukunan dalam keluarga, masyarakat, dan negara","kerukunan antar partai politik"],"a":1,"ex":"Tri kerukunan: (1) intern umat beragama, (2) antarumat beragama, dan (3) antara umat beragama dengan pemerintah."},
{"id":"TWK-1556","q":"FKUB yang dibentuk di setiap provinsi dan kabupaten/kota adalah singkatan dari ....","opts":["Federasi Kerukunan Umat Beragama","Forum Kebangsaan Umat Beragama","Front Kerukunan Umat Beragama","Forum Komunikasi Umat Beragama","Forum Kerukunan Umat Beragama"],"a":4,"ex":"FKUB adalah Forum Kerukunan Umat Beragama, wadah dialog para pemuka agama untuk memelihara kerukunan."},
{"id":"TWK-1557","q":"Berdasarkan Peraturan Bersama Menteri tahun 2006, pendirian rumah ibadat memerlukan ....","opts":["izin dari tokoh agama setempat saja","90 pengguna dan 60 dukungan warga setempat","persetujuan seluruh warga desa","izin tertulis dari Presiden","100 pengguna tanpa syarat lain"],"a":1,"ex":"PBM No. 9 dan 8 Tahun 2006 mensyaratkan daftar 90 pengguna rumah ibadat dan dukungan minimal 60 warga setempat yang disahkan lurah/kepala desa."},
{"id":"TWK-1558","q":"Kementerian Agama Republik Indonesia dibentuk pada tanggal ....","opts":["10 November 1945","1 Juni 1945","17 Agustus 1945","3 Januari 1946","20 Mei 1948"],"a":3,"ex":"Kementerian Agama dibentuk pada 3 Januari 1946 sebagai wujud perhatian negara terhadap kehidupan beragama."},
{"id":"TWK-1559","q":"Menteri Agama pertama Republik Indonesia adalah ....","opts":["H.M. Rasjidi","KH Mas Mansur","Agus Salim","Moh. Natsir","KH Wahid Hasyim"],"a":0,"ex":"Menteri Agama pertama adalah H.M. Rasjidi yang menjabat sejak pembentukan Kementerian Agama pada 3 Januari 1946."},
{"id":"TWK-1560","q":"Program moderasi beragama yang digagas Kementerian Agama bertujuan ....","opts":["menetapkan satu tafsir resmi setiap agama","menyeragamkan seluruh ajaran agama","menumbuhkan cara beragama yang moderat, toleran, dan menolak ekstremisme","membatasi kegiatan keagamaan","menghapus perbedaan antaragama"],"a":2,"ex":"Moderasi beragama adalah cara pandang dan praktik beragama yang moderat: toleran, menghargai perbedaan, dan menolak kekerasan atas nama agama."},
{"id":"TWK-1561","q":"Contoh nyata kerukunan antarumat beragama dalam kehidupan sehari-hari adalah ....","opts":["memaksa orang lain mengikuti keyakinan kita","menyebarkan ujaran kebencian di media sosial","menutup rumah ibadat agama lain","melarang tetangga beribadah","ikut menjaga keamanan saat umat lain merayakan hari raya"],"a":4,"ex":"Toleransi diwujudkan dengan saling menghormati, misalnya ikut menjaga ketertiban saat umat agama lain merayakan hari besar keagamaannya."},
{"id":"TWK-1562","q":"Apabila terjadi perselisihan antarumat beragama di suatu daerah, langkah yang paling tepat adalah ....","opts":["membiarkan konflik meluas","menyelesaikannya melalui dialog dan musyawarah dengan melibatkan tokoh agama dan FKUB","mengusir salah satu kelompok","melaporkan ke media asing","menggunakan kekerasan"],"a":1,"ex":"Konflik keagamaan diselesaikan melalui dialog, musyawarah, dan mediasi dengan melibatkan tokoh agama, FKUB, serta aparat pemerintah."},
{"id":"TWK-1563","q":"Hari-hari besar keagamaan seperti Idulfitri, Natal, Nyepi, Waisak, dan Imlek ditetapkan sebagai hari libur nasional. Hal ini menunjukkan ....","opts":["libur nasional hanya untuk umat beragama","pemerintah mencampuri ajaran agama","negara memihak satu agama","negara menghormati dan menjamin kehidupan beragama seluruh pemeluk agama","agama mengatur pemerintahan"],"a":3,"ex":"Penetapan hari besar keagamaan sebagai libur nasional adalah wujud penghormatan dan jaminan negara atas kebebasan beragama."},
{"id":"TWK-1564","q":"Penyebaran ajaran agama kepada orang lain harus dilakukan ....","opts":["dengan cara yang santun tanpa paksaan","dengan iming-iming materi semata","dengan menjelekkan agama lain","dengan kekerasan","dengan paksaan dan ancaman"],"a":0,"ex":"Kebebasan beragama mencakup berdakwah, tetapi harus dengan cara yang santun, damai, dan tanpa paksaan terhadap orang lain."},
{"id":"TWK-1565","q":"Kebebasan beragama yang dijamin konstitusi bukan berarti bebas ....","opts":["mempelajari kitab suci","mendirikan rumah ibadat","menodai atau menghina agama orang lain","merayakan hari besar keagamaan","beribadah menurut keyakinannya"],"a":2,"ex":"Kebebasan beragama dibatasi oleh hak orang lain; menodai atau menghina agama lain dapat dipidana berdasarkan UU PNPS No. 1 Tahun 1965."},
{"id":"TWK-1566","q":"Sila pertama Pancasila menjadi landasan kerukunan umat beragama karena ....","opts":["melarang pendirian rumah ibadat","mengatur tata cara ibadah","menyeragamkan seluruh ajaran agama","menetapkan satu agama negara","menjamin kebebasan beragama dan mewajibkan toleransi antarumat beragama"],"a":4,"ex":"Ketuhanan Yang Maha Esa menegaskan bangsa Indonesia adalah bangsa yang beragama dan menjunjung tinggi toleransi serta kerukunan antarumat beragama."},
{"id":"TWK-1567","q":"Tempat ibadah umat Islam, Kristen, Hindu, Buddha, dan Konghucu berturut-turut adalah ....","opts":["masjid, gereja, pura, vihara, klenteng","gereja, masjid, vihara, pura, klenteng","masjid, pura, gereja, klenteng, vihara","klenteng, vihara, pura, gereja, masjid","masjid, gereja, vihara, pura, klenteng"],"a":0,"ex":"Tempat ibadah: Islam di masjid, Kristen di gereja, Hindu di pura, Buddha di vihara, dan Konghucu di klenteng."},
{"id":"TWK-1568","q":"Putusan Mahkamah Konstitusi No. 97/PUU-XIV/2016 menegaskan bahwa ....","opts":["kolom agama KTP dihapuskan","kepercayaan lokal harus dibubarkan","penghayat kepercayaan dilarang","penghayat kepercayaan berhak mencantumkan kepercayaannya pada KTP","hanya enam agama yang boleh dianut"],"a":3,"ex":"MK memutuskan penghayat kepercayaan berhak mencantumkan 'Kepercayaan terhadap Tuhan YME' pada kolom agama KTP sebagai wujud keadilan."},
{"id":"TWK-1569","q":"Peran tokoh agama dalam memelihara kerukunan umat beragama adalah ....","opts":["menjadi teladan toleransi dan menyerukan perdamaian","menutup diri dari umat agama lain","mencampuri urusan pemerintahan","melarang dialog antarumat beragama","memprovokasi umatnya membenci agama lain"],"a":0,"ex":"Tokoh agama berperan sebagai teladan toleransi, menyerukan perdamaian, dan aktif dalam dialog antarumat beragama."},
{"id":"TWK-1570","q":"Semboyan Bhinneka Tunggal Ika berkaitan dengan kerukunan umat beragama karena ....","opts":["mewajibkan konversi agama","menghapus perbedaan agama","mengajarkan persatuan dalam keberagaman, termasuk keberagaman agama","menetapkan satu agama mayoritas","melarang perbedaan keyakinan"],"a":2,"ex":"Bhinneka Tunggal Ika berarti berbeda-beda tetapi tetap satu: keberagaman agama justru dipersatukan dalam bingkai Indonesia."},
{"id":"TWK-1571","q":"Kantor Urusan Agama (KUA) di tingkat kecamatan memiliki tugas antara lain ....","opts":["penerbitan KTP","pengelolaan dana desa","penyelenggaraan pemilihan umum","mengatur pajak warga","pencatatan pernikahan dan pembinaan kehidupan beragama"],"a":4,"ex":"KUA bertugas dalam pencatatan nikah, pembinaan keluarga sakinah, dan pembinaan kehidupan beragama di tingkat kecamatan."},
{"id":"TWK-1572","q":"Penyelenggaraan ibadah haji di Indonesia dikoordinasikan oleh ....","opts":["Kementerian Luar Negeri","Kementerian Agama","Kementerian Pariwisata","Pemerintah Arab Saudi semata","organisasi masyarakat"],"a":1,"ex":"Kementerian Agama menyelenggarakan urusan haji, mulai dari pendaftaran, pembinaan, hingga pemberangkatan jemaah."},
{"id":"TWK-1573","q":"Sikap yang tepat ketika mendengar ceramah yang berisi ujaran kebencian terhadap agama lain adalah ....","opts":["membalas dengan ujaran kebencian","mengajak orang lain membenci","ikut menyebarluaskannya","tidak menyebarkan dan melaporkannya melalui jalur yang benar","mendiamkan saja tanpa peduli"],"a":3,"ex":"Ujaran kebencian berlatar agama merusak kerukunan; warga yang baik tidak menyebarkannya dan dapat melapor ke aparat atau platform terkait."},
{"id":"TWK-1574","q":"Gotong royong membersihkan lingkungan yang melibatkan warga lintas agama mencerminkan ....","opts":["pelanggaran kebebasan beragama","pencampuran ajaran agama","penghapusan identitas agama","kewajiban pemerintah semata","pengamalan sila pertama dan ketiga"],"a":4,"ex":"Kerja sama lintas agama mencerminkan sila pertama (kerukunan beragama) dan sila ketiga (persatuan Indonesia)."},
{"id":"TWK-1575","q":"Dialog antarumat beragama bertujuan untuk ....","opts":["menghapus perbedaan keyakinan","menyatukan seluruh ajaran agama","saling memahami dan membangun kepercayaan antarumat beragama","mencari kelemahan agama lain","menentukan agama yang paling benar"],"a":2,"ex":"Dialog antarumat beragama bertujuan membangun saling pengertian dan kepercayaan, bukan menyatukan atau menilai ajaran agama."},
{"id":"TWK-1576","q":"Tindakan intoleran seperti melarang pendirian rumah ibadat yang telah memenuhi syarat bertentangan dengan ....","opts":["kewenangan pemerintah daerah","adat istiadat setempat","kepentingan mayoritas","kebebasan mutlak tanpa aturan","Pasal 29 UUD 1945 dan prinsip kerukunan umat beragama"],"a":4,"ex":"Setiap pemeluk agama berhak beribadat; menghalangi rumah ibadat yang memenuhi syarat melanggar jaminan konstitusi Pasal 29 UUD 1945."},
{"id":"TWK-1577","q":"Moderasi beragama menolak ekstremisme karena ekstremisme ....","opts":["mendukung kerukunan","dapat memicu konflik dan memecah persatuan bangsa","sesuai dengan ajaran agama","dijamin oleh konstitusi","memperkuat toleransi"],"a":1,"ex":"Ekstremisme beragama memicu konflik horizontal dan mengancam persatuan, sehingga bertentangan dengan moderasi beragama dan Pancasila."},
{"id":"TWK-1578","q":"Bentuk toleransi beragama di lingkungan sekolah adalah ....","opts":["memisahkan siswa berdasarkan agama secara kaku","meniadakan pelajaran agama","memaksa siswa mengikuti ibadah agama tertentu","menghormati teman yang sedang menjalankan ibadah puasa","melarang siswa berdiskusi tentang agama"],"a":3,"ex":"Toleransi di sekolah diwujudkan dengan menghormati praktik ibadah teman berbeda agama, misalnya tidak makan di depannya saat berpuasa."},
{"id":"TWK-1579","q":"Kebebasan memeluk agama menurut Pasal 28I UUD 1945 termasuk ....","opts":["hak yang tidak dapat dikurangi dalam keadaan apa pun","hak khusus aparatur negara","hak yang hanya berlaku di kota besar","hak yang memerlukan izin pemerintah","hak yang dapat dikurangi dalam keadaan apa pun"],"a":0,"ex":"Pasal 28I: hak untuk hidup, tidak disiksa, kemerdekaan pikiran dan hati nurani, memeluk agama, dan tidak diperbudak adalah hak yang tidak dapat dikurangi dalam keadaan apa pun."},
{"id":"TWK-1580","q":"Wujud nyata kerukunan intern umat beragama adalah ....","opts":["membubarkan perbedaan mazhab","umat satu agama hidup rukun meski berbeda organisasi atau mazhab","menolak perbedaan pendapat dalam agama","menyeragamkan seluruh ritual keagamaan","melarang organisasi keagamaan"],"a":1,"ex":"Kerukunan intern berarti umat seagama hidup rukun walaupun berbeda organisasi, mazhab, atau penafsiran dalam agamanya."},
{"id":"TWK-1581","q":"Huruf kapital digunakan pada ....","opts":["kata depan di tengah kalimat","kata ulang berimbuhan","kata seru dalam kalimat","tengah kata secara acak","awal kalimat"],"a":4,"ex":"Huruf kapital dipakai pada awal kalimat, nama orang, nama geografi, nama hari/bulan, peristiwa sejarah, dan nama lembaga resmi."},
{"id":"TWK-1582","q":"Penulisan kalimat yang tepat adalah ....","opts":["presiden Joko Widodo berkunjung ke Jawa Timur.","Presiden joko widodo berkunjung ke Jawa Timur.","Presiden Joko Widodo berkunjung ke Jawa Timur.","Presiden Joko Widodo berkunjung ke jawa timur.","presiden joko widodo berkunjung ke jawa timur."],"a":2,"ex":"Awal kalimat kapital, jabatan yang diikuti nama orang kapital (Presiden Joko Widodo), dan nama geografi kapital (Jawa Timur)."},
{"id":"TWK-1583","q":"Penulisan nama geografi yang tepat adalah ....","opts":["Pulau Jawa","PULAU JAWA","pulau jawa","Pulau jawa","pulau Jawa"],"a":0,"ex":"Nama geografi ditulis dengan huruf kapital pada setiap unsurnya: Pulau Jawa, Sungai Musi, Danau Toba."},
{"id":"TWK-1584","q":"Penulisan nama hari dan bulan yang tepat adalah ....","opts":["Senin, januari","senin, Januari","Senin, Januari","SENIN, JANUARI","senin, januari"],"a":2,"ex":"Nama hari dan bulan ditulis dengan huruf kapital: Senin, Januari."},
{"id":"TWK-1585","q":"Penulisan peristiwa sejarah yang tepat adalah ....","opts":["PROKLAMASI KEMERDEKAAN INDONESIA","proklamasi kemerdekaan Indonesia","Proklamasi kemerdekaan Indonesia","Proklamasi Kemerdekaan Indonesia","proklamasi Kemerdekaan Indonesia"],"a":3,"ex":"Nama peristiwa sejarah ditulis dengan huruf kapital pada setiap kata: Proklamasi Kemerdekaan Indonesia, Sumpah Pemuda."},
{"id":"TWK-1586","q":"Penulisan nama lembaga resmi yang tepat adalah ....","opts":["Dewan perwakilan rakyat","DEWAN PERWAKILAN RAKYAT","Dewan Perwakilan rakyat","dewan perwakilan rakyat","Dewan Perwakilan Rakyat"],"a":4,"ex":"Nama badan/lembaga resmi ditulis dengan huruf kapital: Dewan Perwakilan Rakyat, Mahkamah Konstitusi."},
{"id":"TWK-1587","q":"Penulisan kata ganti untuk Tuhan yang tepat adalah ....","opts":["tuhan yang maha esa","Tuhan yang maha esa","Tuhan Yang Maha Esa","tuhan Yang Maha Esa","TUHAN YANG MAHA ESA"],"a":2,"ex":"Kata Tuhan dan kata ganti-Nya ditulis dengan huruf kapital: Tuhan Yang Maha Esa, rahmat-Nya."},
{"id":"TWK-1588","q":"Penulisan yang tepat untuk bahasa nasional adalah ....","opts":["Bahasa Indonesia","BAHASA INDONESIA","bahasa indonesia","Bahasa indonesia","bahasa Indonesia"],"a":4,"ex":"Kata bahasa tidak dikapitalkan, sedangkan nama bahasanya dikapitalkan: bahasa Indonesia, bahasa Inggris."},
{"id":"TWK-1589","q":"Tanda titik digunakan untuk ....","opts":["mengakhiri kalimat berita","mengakhiri kalimat tanya","memisahkan anak kalimat","menandai kutipan langsung","mengakhiri kalimat perintah"],"a":0,"ex":"Tanda titik dipakai pada akhir kalimat berita/pernyataan, misalnya: Indonesia merdeka pada tahun 1945."},
{"id":"TWK-1590","q":"Penulisan singkatan gelar yang tepat adalah ....","opts":["S H","SH","S.H","S.H.","sh"],"a":3,"ex":"Singkatan nama gelar dan jabatan memakai tanda titik pada setiap huruf: S.H., S.E., Ir."},
{"id":"TWK-1591","q":"Tanda koma digunakan untuk ....","opts":["mengakhiri kalimat tanya","menandai dialog langsung","menyatakan perbandingan","mengakhiri kalimat berita","memisahkan unsur-unsur dalam pemerincian"],"a":4,"ex":"Tanda koma dipakai memisahkan unsur dalam pemerincian, misalnya: Saya membeli buku, pensil, dan penghapus."},
{"id":"TWK-1592","q":"Tanda koma dipakai sebelum kata penghubung ....","opts":["dan","serta","tetapi dan melainkan","karena","sehingga"],"a":2,"ex":"Tanda koma dipakai sebelum kata tetapi, melainkan, dan sedangkan dalam kalimat majemuk setara."},
{"id":"TWK-1593","q":"Tanda titik dua digunakan ....","opts":["menggantikan tanda koma","sebelum kutipan tidak langsung","di akhir kalimat tanya","sesudah kata atau ungkapan yang memerlukan pemerincian","di awal kalimat berita"],"a":3,"ex":"Tanda titik dua dipakai sesudah kata yang memerlukan pemerincian, misalnya: Mereka memerlukan perlengkapan: tas, buku, dan alat tulis."},
{"id":"TWK-1594","q":"Tanda hubung digunakan dalam penulisan ....","opts":["kalimat berita","singkatan gelar","kutipan langsung","angka desimal","kata ulang seperti berulang-ulang"],"a":4,"ex":"Tanda hubung dipakai pada kata ulang (berulang-ulang), kata berimbuhan dengan singkatan (ke-2), dan rentang (tahun 1945-1949)."},
{"id":"TWK-1595","q":"Tanda tanya digunakan untuk ....","opts":["menandai judul karangan","mengakhiri kalimat berita","mengakhiri kalimat perintah","mengakhiri kalimat tanya","memisahkan pemerincian"],"a":3,"ex":"Tanda tanya dipakai pada akhir kalimat tanya, misalnya: Kapan Indonesia merdeka?"},
{"id":"TWK-1596","q":"Tanda seru digunakan untuk ....","opts":["mengakhiri pernyataan perintah atau seruan yang kuat","memisahkan unsur pemerincian","menandai singkatan","mengakhiri kalimat berita","mengakhiri kalimat tanya"],"a":0,"ex":"Tanda seru dipakai sesudah pernyataan perintah, seruan, atau ungkapan emosi yang kuat, misalnya: Berdirilah!"},
{"id":"TWK-1597","q":"Tanda petik digunakan untuk ....","opts":["mengapit kutipan langsung dan judul karya","mengakhiri kalimat berita","memisahkan kalimat setara","menandai singkatan","menunjukkan kepemilikan"],"a":0,"ex":"Tanda petik mengapit kutipan langsung, misalnya: Ia berkata, 'Saya siap.' serta judul sajak, lagu, atau film."},
{"id":"TWK-1598","q":"Tanda elipsis (...) digunakan untuk ....","opts":["menandai kutipan langsung","mengakhiri kalimat perintah","mengakhiri kalimat berita","menunjukkan kalimat yang terputus-putus","memisahkan pemerincian"],"a":3,"ex":"Tanda elipsis menunjukkan bahwa dalam suatu kalimat ada bagian yang dihilangkan atau kalimat terputus, misalnya: Sebab-sebab kemunduran ... akan dibahas."},
{"id":"TWK-1599","q":"Tanda titik koma digunakan untuk ....","opts":["memisahkan bagian kalimat setara yang sudah memakai koma","mengapit kutipan langsung","menandai singkatan gelar","mengakhiri kalimat perintah","mengakhiri kalimat tanya"],"a":0,"ex":"Tanda titik koma memisahkan kalimat setara yang satu dengan yang lain yang sudah memakai koma di dalamnya."},
{"id":"TWK-1600","q":"Penulisan bilangan pada awal kalimat yang tepat adalah ....","opts":["5-orang siswa mengikuti lomba.","5 orang siswa mengikuti lomba.","Lima orang siswa mengikuti lomba.","lima orang siswa mengikuti lomba.","V orang siswa mengikuti lomba."],"a":2,"ex":"Bilangan pada awal kalimat ditulis dengan huruf dan diawali huruf kapital: Lima orang siswa mengikuti lomba."},
{"id":"TWK-1601","q":"Perang proksi (proxy war) adalah ....","opts":["perang saudara dalam satu negara","perang dagang antarnegara","latihan perang bersama antarnegara","perang terbuka antarnegara dengan senjata nuklir","perang yang dilakukan melalui pihak ketiga tanpa konfrontasi militer langsung"],"a":4,"ex":"Proxy war adalah konflik yang dijalankan melalui pihak ketiga (kelompok bersenjata, disinformasi, tekanan ekonomi) tanpa perang terbuka langsung."},
{"id":"TWK-1602","q":"Ancaman hibrida (hybrid threat) merupakan gabungan dari ....","opts":["serangan militer konvensional saja","ancaman militer dan nonmiliter seperti serangan siber, disinformasi, dan tekanan ekonomi","bencana alam dan wabah penyakit","konflik antar suku","persaingan olahraga"],"a":1,"ex":"Ancaman hibrida memadukan cara militer dan nonmiliter: serangan siber, perang informasi, tekanan ekonomi, dan operasi intelijen."},
{"id":"TWK-1603","q":"Contoh nyata perang proksi di era modern adalah ....","opts":["kerja sama perdagangan","festival budaya internasional","latihan militer bersama","penyebaran disinformasi dan adu domba melalui media sosial oleh pihak asing","pertukaran pelajar"],"a":3,"ex":"Proxy war modern berbentuk disinformasi, propaganda, dan adu domba via media sosial untuk melemahkan suatu negara dari dalam."},
{"id":"TWK-1604","q":"Lembaga negara yang bertanggung jawab atas keamanan siber nasional adalah ....","opts":["Badan Siber dan Sandi Negara","Badan Intelijen Negara","Kementerian Komunikasi dan Digital semata","Kepolisian lalu lintas","Komisi Pemberantasan Korupsi"],"a":0,"ex":"BSSN (Badan Siber dan Sandi Negara), dibentuk melalui Perpres No. 53 Tahun 2017, bertanggung jawab atas keamanan siber nasional."},
{"id":"TWK-1605","q":"Tugas utama Badan Siber dan Sandi Negara (BSSN) adalah ....","opts":["mengelola pajak digital","menangkap pelaku kejahatan jalanan","melaksanakan keamanan siber secara efektif dan efisien","mengatur lalu lintas internet untuk hiburan","menyensor seluruh media sosial"],"a":2,"ex":"BSSN bertugas melaksanakan keamanan siber: melindungi infrastruktur kritis, menangani insiden siber, dan membangun ketahanan siber nasional."},
{"id":"TWK-1606","q":"Undang-Undang Informasi dan Transaksi Elektronik (UU ITE) pertama kali diundangkan pada tahun ....","opts":["2014","2019","2024","2004","2008"],"a":4,"ex":"UU ITE pertama adalah UU No. 11 Tahun 2008, kemudian diubah dengan UU No. 19 Tahun 2016 dan UU No. 1 Tahun 2024."},
{"id":"TWK-1607","q":"Penyebaran hoaks yang memecah belah persatuan bangsa termasuk ancaman ....","opts":["militer","nonmiliter di bidang ideologi, politik, dan informasi","bencana alam","tidak termasuk ancaman negara","kriminalitas biasa semata"],"a":1,"ex":"Hoaks dan disinformasi adalah ancaman nonmiliter yang menyerang ideologi, politik, dan sosial budaya bangsa."},
{"id":"TWK-1608","q":"Literasi digital bagi warga negara merupakan wujud bela negara karena ....","opts":["meningkatkan kecepatan internet","memperbanyak konten hiburan","menambah pengguna internet","membuat warga kritis terhadap hoaks dan disinformasi yang mengancam persatuan","mengurangi belanja negara"],"a":3,"ex":"Warga yang literat digital tidak mudah diprovokasi hoaks dan perang informasi, sehingga ikut mempertahankan keutuhan bangsa di ruang siber."},
{"id":"TWK-1609","q":"Undang-Undang No. 27 Tahun 2022 mengatur tentang ....","opts":["pelindungan data pribadi","keamanan siber nasional","intelijen negara","pertahanan negara","informasi dan transaksi elektronik"],"a":0,"ex":"UU No. 27 Tahun 2022 tentang Pelindungan Data Pribadi melindungi data warga dari penyalahgunaan, termasuk oleh serangan siber."},
{"id":"TWK-1610","q":"Serangan siber terhadap infrastruktur kritis seperti listrik dan perbankan berbahaya karena ....","opts":["hanya menyerang perangkat pribadi","hanya merugikan satu perusahaan","dapat melumpuhkan layanan publik dan mengganggu stabilitas nasional","tidak berdampak pada masyarakat","mudah diperbaiki dalam hitungan detik"],"a":2,"ex":"Infrastruktur kritis menopang kehidupan nasional; serangannya dapat melumpuhkan layanan publik, ekonomi, dan stabilitas negara."},
{"id":"TWK-1611","q":"Perang informasi (information warfare) dilakukan dengan cara ....","opts":["blokade ekonomi total","invasi darat","serangan udara","serangan fisik ke markas militer","propaganda, disinformasi, dan manipulasi opini publik"],"a":4,"ex":"Perang informasi menggunakan propaganda, hoaks, dan manipulasi opini (termasuk buzzer) untuk memengaruhi dan melemahkan target."},
{"id":"TWK-1612","q":"Strategi pertahanan negara menghadapi ancaman hibrida yang tepat adalah ....","opts":["hanya mengandalkan kekuatan militer","memadukan pertahanan militer dengan ketahanan nonmiliter dan kesadaran digital seluruh warga","menutup seluruh akses internet","menyerahkan pertahanan kepada negara lain","mengabaikan ancaman nonmiliter"],"a":1,"ex":"Ancaman hibrida harus dihadapi dengan sistem pertahanan semesta: TNI sebagai komponen utama didukung seluruh warga, termasuk ketahanan di ruang siber."},
{"id":"TWK-1613","q":"Dalam bela negara di ruang siber, peran warga negara adalah ....","opts":["menyebarkan ujaran kebencian","membobol sistem keamanan","menjadi peretas untuk menyerang negara lain","tidak menyebarkan hoaks, menjaga data pribadi, dan melaporkan konten berbahaya","pasif dan tidak peduli"],"a":3,"ex":"Bela negara di ruang siber: bijak bermedia sosial, tidak menyebar hoaks/ujaran kebencian, menjaga data pribadi, dan melaporkan konten berbahaya."},
{"id":"TWK-1614","q":"Etika bermedia sosial sebagai wujud bela negara ditunjukkan dengan ....","opts":["memverifikasi informasi sebelum membagikannya","menggunakan akun anonim untuk memprovokasi","menyebarkan data pribadi orang lain","mengadu domba kelompok masyarakat","menyebarluaskan setiap informasi tanpa verifikasi"],"a":0,"ex":"Saring sebelum sharing: memverifikasi kebenaran informasi sebelum dibagikan adalah etika digital sekaligus bela negara."},
{"id":"TWK-1615","q":"Ancaman nonmiliter terhadap ketahanan nasional meliputi bidang ....","opts":["hanya persaingan dagang","ideologi, politik, ekonomi, sosial budaya, dan teknologi informasi","hanya bidang militer","hanya bencana alam","hanya kejahatan jalanan"],"a":1,"ex":"Ancaman nonmiliter mencakup ideologi, politik, ekonomi, sosial budaya, teknologi informasi, serta keselamatan umum."},
{"id":"TWK-1616","q":"Bentuk perang proksi di bidang ekonomi antara lain ....","opts":["investasi yang saling menguntungkan","pariwisata internasional","pertukaran budaya","bantuan kemanusiaan","ketergantungan ekonomi dan perang dagang yang melemahkan kedaulatan"],"a":4,"ex":"Proxy war ekonomi berbentuk ketergantungan, perang dagang, dan tekanan ekonomi untuk melemahkan kedaulatan suatu negara."},
{"id":"TWK-1617","q":"Upaya menangkal penyebaran paham radikal di dunia maya yang tepat adalah ....","opts":["melarang seluruh penggunaan internet","kontra-narasi, literasi digital, dan penegakan hukum terhadap penyebar paham radikal","membiarkan tanpa tindakan","menutup semua media sosial","menghapus seluruh konten keagamaan"],"a":1,"ex":"Penangkalan dilakukan melalui kontra-narasi perdamaian, penguatan literasi digital, dan penegakan hukum (UU ITE, UU Terorisme)."},
{"id":"TWK-1618","q":"Keamanan data pada instansi pemerintah penting karena kebocoran data dapat ....","opts":["mempercepat layanan publik","meningkatkan kepercayaan publik","tidak menimbulkan dampak apa pun","dimanfaatkan pihak asing untuk spionase dan melemahkan negara","hanya merugikan satu pegawai"],"a":3,"ex":"Kebocoran data pemerintah dapat dimanfaatkan untuk spionase, pemerasan, dan serangan lanjutan yang mengancam keamanan nasional."},
{"id":"TWK-1619","q":"Perang proksi pada era digital banyak menyasar generasi muda karena ....","opts":["generasi muda adalah pengguna utama media sosial sehingga mudah dipengaruhi","generasi muda kebal terhadap propaganda","generasi muda tidak peduli politik","generasi muda sulit dijangkau","generasi muda tidak menggunakan internet"],"a":0,"ex":"Generasi muda sebagai pengguna utama media sosial menjadi sasaran empuk propaganda, disinformasi, dan rekrutmen paham radikal."},
{"id":"TWK-1620","q":"Wujud bela negara di era digital yang paling sederhana adalah ....","opts":["berlangganan internet tercepat","membeli perangkat tercanggih","tidak menyebarkan hoaks dan menjaga keamanan data pribadi","menjadi selebritas media sosial","mengoleksi gawai terbanyak"],"a":2,"ex":"Bela negara di era digital dimulai dari hal sederhana: saring sebelum sharing, tidak menyebar hoaks, dan menjaga data pribadi."}
];
